import chess
import chess.pgn
import json
import io

def levenshtein(s1, s2):
    if len(s1) < len(s2):
        return levenshtein(s2, s1)
    if len(s2) == 0:
        return len(s1)
    prev_row = range(len(s2) + 1)
    for i, c1 in enumerate(s1):
        curr_row = [i + 1]
        for j, c2 in enumerate(s2):
            insertions = prev_row[j + 1] + 1
            deletions = curr_row[j] + 1
            substitutions = prev_row[j] + (c1 != c2)
            curr_row.append(min(insertions, deletions, substitutions))
        prev_row = curr_row
    return prev_row[-1]

def find_closest_legal_move(board, bad_token):
    """Find the closest legal move to the given bad token."""
    best_alt = None
    best_dist = 999

    for legal_move in board.legal_moves:
        san = board.san(legal_move)
        dist = levenshtein(bad_token, san)
        if dist < best_dist:
            best_dist = dist
            best_alt = san
        if dist <= 1:
            return san

    if best_alt and best_dist <= 3:
        return best_alt
    return None

def repair_game(pgn_text, game_id):
    """Repair a corrupted PGN game."""
    errors_found = []

    lines = pgn_text.strip().split('\n')
    headers = []
    move_lines = []
    in_moves = False

    for line in lines:
        stripped = line.strip()
        if stripped.startswith('[') and stripped.endswith(']'):
            headers.append(line)
        elif stripped == '':
            if headers:
                in_moves = True
        elif in_moves or not stripped.startswith('['):
            move_lines.append(stripped)
            in_moves = True

    move_text = ' '.join(move_lines)
    board = chess.Board()
    tokens = move_text.split()
    repaired_tokens = []
    i = 0

    while i < len(tokens):
        token = tokens[i]

        if token.endswith('.') and token[:-1].isdigit():
            repaired_tokens.append(token)
            i += 1
            continue

        if token in ['1-0', '0-1', '1/2-1/2', '*']:
            repaired_tokens.append(token)
            i += 1
            continue

        try:
            san = board.san(board.parse_san(token))
            repaired_tokens.append(token)
            board.push(board.parse_san(token))
            i += 1
            continue
        except:
            pass

        fixed_move = find_closest_legal_move(board, token)

        if fixed_move:
            errors_found.append(f"illegal move {token} fixed to {fixed_move}")
            repaired_tokens.append(fixed_move)
            board.push(board.parse_san(fixed_move))
            i += 1
        else:
            errors_found.append(f"unfixable illegal move {token}")
            repaired_tokens.append(token)
            i += 1

    move_str = ' '.join(repaired_tokens)
    repaired_pgn = '\n'.join(headers) + '\n\n' + move_str
