            substitutions = prev_row[j] + (c1 != c2)
            curr_row.append(min(insertions, deletions, substitutions))
        prev_row = curr_row
    return prev_row[-1]

def find_closest_legal_move(board, bad_token):
    best_alt = None
    best_dist = 999
    for legal_move in board.legal_moves:
        san = board.san(legal_move)
        dist = levenshtein(bad_token, san)
        if dist < best_dist:
            best_dist = dist
            best_alt = san
        if dist <= 1:
            return san
    if best_alt and best_dist <= 3:
        return best_alt
    return None

def repair_game(pgn_text, game_id):
    errors_found = []
    lines = pgn_text.strip().split('\n')
    headers = []
    move_lines = []
    in_moves = False
    for line in lines:
        stripped = line.strip()
        if stripped.startswith('[') and stripped.endswith(']'):
            headers.append(line)
        elif stripped == '':
            if headers:
                in_moves = True
        elif in_moves or not stripped.startswith('['):
            move_lines.append(stripped)
            in_moves = True

    move_text = ' '.join(move_lines)
    board = chess.Board()
    tokens = move_text.split()
    repaired_tokens = []

    for token in tokens:
        if token.endswith('.') and token[:-1].isdigit():
            repaired_tokens.append(token)
            continue
        if token in ['1-0', '0-1', '1/2-1/2', '*']:
            repaired_tokens.append(token)
            continue

        try:
            board.push(board.parse_san(token))
            repaired_tokens.append(token)
            continue
        except:
            pass

        fixed = find_closest_legal_move(board, token)
        if fixed:
            errors_found.append(f"illegal move {token} fixed to {fixed}")
            repaired_tokens.append(fixed)
            board.push(board.parse_san(fixed))
        else:
            errors_found.append(f"unfixable illegal move {token}")
            repaired_tokens.append(token)

    repaired_pgn = '\n'.join(headers) + '\n\n' + ' '.join(repaired_tokens)
    return repaired_pgn, errors_found, board

def simple_eval(board):
    pv = {chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330,
          chess.ROOK: 500, chess.QUEEN: 900, chess.KING: 20000}
    score = 0
    for pt in pv:
        score += (len(board.pieces(pt, chess.WHITE)) - len(board.pieces(pt, chess.BLACK))) * pv[pt]
    return score / 100.0

def analyze_game(board):
    best_eval = 0.0
    critical_move = 0
    temp = chess.Board()
    for move in board.move_stack:
        temp.push(move)
        ev = simple_eval(temp)
        if abs(ev) > abs(best_eval):
            best_eval = ev
            critical_move = len(temp.move_stack)
    sign = "+" if best_eval >= 0 else ""
    return {"move_number": critical_move, "evaluation": f"{sign}{best_eval:.1f}"}

def find_forced_mate(board, max_ply):
    """Find forced mate within max_ply plies. Returns (moves_list, half_moves) or None."""
    if board.is_checkmate():
        return [], 0
    if max_ply <= 0:
        return None

    for move in board.legal_moves:
        san = board.san(move)
        board.push(move)

        if board.is_checkmate():
            board.pop()
            return [san], 1

        # Check if ALL opponent replies lead to mate
        all_lead_to_mate = True
        best_reply_info = None
        min_remaining = float('inf')

        for reply in board.legal_moves:
            reply_san = board.san(reply)
            board.push(reply)
            result = find_forced_mate(board, max_ply - 2)
            board.pop()
            if result is None:
                all_lead_to_mate = False
                break
            else:
                ml, depth = result
                if depth < min_remaining:
                    min_remaining = depth
                    best_reply_info = (reply_san, ml)

        if all_lead_to_mate and best_reply_info:
            rsan, rest = best_reply_info
            full_seq = [san, rsan] + rest
            board.pop()
            return full_seq, len(full_seq) // 2 + 1

        board.pop()
    return None

def solve_puzzle(puzzle):
    board = chess.Board(puzzle["fen"])
    desc = puzzle.get("description", "")

    mate_in_target = None
    if "mate in" in desc.lower():
        try:
            mate_in_target = int(desc.split("mate in")[1].strip().split()[0])
        except:
            pass

    # Try to find forced mate
    actual_mate = None
    if mate_in_target:
        for depth in range(1, mate_in_target + 1):
            result = find_forced_mate(board, depth * 2)
            if result:
                moves, half_moves = result
                actual_mate = {"moves": moves, "half_moves": half_moves}
                break
        if not actual_mate:
            # Try up to the target depth
            result = find_forced_mate(board, mate_in_target * 2)
            if result:
                moves, half_moves = result
                actual_mate = {"moves": moves, "half_moves": half_moves}

    if actual_mate:
        return {
            "puzzle_id": puzzle["id"],
            "best_move": actual_mate["moves"][0],
            "continuation": actual_mate["moves"],
            "mate_in": actual_mate["half_moves"]
        }

    # Find best move by material gain
    best_move = None
    best_move_obj = None
    best_score = -99999
    for move in board.legal_moves:
        san = board.san(move)
        board.push(move)
        score = simple_eval(board)
        board.pop()
        if score > best_score:
            best_score = score
            best_move = san
            best_move_obj = move

    continuation = []
    if best_move_obj:
        continuation.append(best_move)
        board.push(best_move_obj)
        if board.is_checkmate():
            board.pop()
            return {"puzzle_id": puzzle["id"], "best_move": best_move,
                    "continuation": continuation, "mate_in": 1}
        if not board.is_game_over():
            best_reply = None
            best_reply_obj = None
            best_reply_score = 99999
            for reply in board.legal_moves:
                rsan = board.san(reply)
                board.push(reply)
                score = simple_eval(board)
                board.pop()
                if score < best_reply_score:
                    best_reply_score = score
                    best_reply = rsan
                    best_reply_obj = reply
            if best_reply_obj:
                continuation.append(best_reply)
                board.push(best_reply_obj)
                if board.is_checkmate():
                    board.pop()
                    board.pop()
                    return {"puzzle_id": puzzle["id"], "best_move": best_move,
                            "continuation": continuation, "mate_in": 2}
                board.pop()
        board.pop()

    return {"puzzle_id": puzzle["id"], "best_move": best_move or "",
            "continuation": continuation, "mate_in": None}

